/**
 * The extension's manifest (Manifest V3), generated by scripts/build.mjs.
 *
 * Production permissions are deliberately minimal and tested
 * (test/manifest.test.ts):
 *   activeTab  access to the page you are on, only after you click the toolbar
 *              icon, and only for that tab until it navigates away
 *   scripting  inject the checks into that page
 *   storage    remember the dashboard address and that the notice was read
 * No host permissions, no content scripts that run on their own, no background
 * worker, nothing reachable from web pages.
 */
export const PRODUCTION_PERMISSIONS = ['activeTab', 'scripting', 'storage'] as const;

export interface ManifestOptions {
  version: string;
  /**
   * TEST BUILDS ONLY: Playwright cannot click the toolbar icon (which is what grants
   * activeTab), so the test build gets access to the local fixture server instead.
   */
  testHostPermissions?: string[];
  /** TEST BUILDS ONLY: a public key, so the test knows the extension ID in advance. */
  testKey?: string;
}

export function buildManifest(options: ManifestOptions): Record<string, unknown> {
  const icons = { 16: 'icons/icon-16.png', 48: 'icons/icon-48.png', 128: 'icons/icon-128.png' };
  return {
    manifest_version: 3,
    name: 'UI Health Checker',
    short_name: 'UI Health',
    version: options.version,
    description:
      'Checks the page you are viewing for accessibility and UI problems, locally in your browser.',
    minimum_chrome_version: '120',
    action: { default_title: 'Check this page', default_popup: 'popup.html', default_icon: icons },
    icons,
    permissions: [...PRODUCTION_PERMISSIONS],
    ...(options.testHostPermissions ? { host_permissions: options.testHostPermissions } : {}),
    ...(options.testKey ? { key: options.testKey } : {}),
  };
}
